def _visible_pump_check_or_403(check_id):
    check = db.session.get(PumpCheck, check_id)
    if not check:
        return None, (jsonify({"error": t("pump.not_found")}), 404)
    if not can_view_pump_check(current_user.id, check):
        return None, (jsonify({"error": t("route.not_friends")}), 403)
    return check, None


def _reload_pump_check(check_id):
    return db.session.get(PumpCheck, check_id)


@bp.route("/pump-check/<int:check_id>/like", methods=["POST"])
@require_auth
def pump_check_like(check_id):
    check, error = _visible_pump_check_or_403(check_id)
    if error:
        return error
    existing = PumpCheckLike.query.filter_by(pump_check_id=check.id, user_id=current_user.id).first()
    if not existing:
        PumpCheck.query.filter_by(id=check.id).update({
            PumpCheck.likes_count: PumpCheck.likes_count + 1,
        }, synchronize_session=False)
        db.session.add(PumpCheckLike(pump_check_id=check.id, user_id=current_user.id))
        # Beğeniyle AYNI transaction'da: rollback olursa bildirim de gitmez.
        notify(check.user_id, "pump_check_like", actor_id=current_user.id,
               target_type="pump_check", target_id=check.id)
        try:
            db.session.commit()
        except IntegrityError:
            db.session.rollback()
    check = _reload_pump_check(check.id)
    return jsonify({"liked": True, "likesCount": check.likes_count or 0})


@bp.route("/pump-check/<int:check_id>/like", methods=["DELETE"])
@require_auth
def pump_check_unlike(check_id):
    check, error = _visible_pump_check_or_403(check_id)
    if error:
        return error
    deleted = PumpCheckLike.query.filter_by(pump_check_id=check.id, user_id=current_user.id).delete(synchronize_session=False)
    if deleted:
        PumpCheck.query.filter_by(id=check.id).update({
            PumpCheck.likes_count: db.case(
                (PumpCheck.likes_count > 0, PumpCheck.likes_count - 1),
                else_=0,
            ),
        }, synchronize_session=False)
        db.session.commit()
    check = _reload_pump_check(check.id)
    return jsonify({"liked": False, "likesCount": check.likes_count or 0})


